#!/bin/bash
# PostToolUse (Edit|Write|MultiEdit): beat_sheet.json · scenes.py · TSX · FACTCHECK.md
# Exit 2 on failures (feeds stderr back to Claude). Fail-open on missing deps (exit 0 + SKIP).
set -euo pipefail

PROJECT_DIR="${CLAUDE_PROJECT_DIR:-/Users/bear/Documents/CoWork/bear-textbooks/books}"
QC="$PROJECT_DIR/brutalist-art/runtime/qc"
SCRIPTS="$PROJECT_DIR/brutalist-art/runtime/scripts"
SCHEMA="$PROJECT_DIR/brutalist-art/runtime/schema/beat_sheet.schema.json"

TMP=$(mktemp /tmp/postedit-XXXXXX.json)
trap 'rm -f "$TMP"' EXIT
cat > "$TMP"

python3 - "$PROJECT_DIR" "$QC" "$SCRIPTS" "$SCHEMA" "$TMP" << 'PYEOF'
import json, os, sys, subprocess, pathlib, importlib.util, re

project_dir = pathlib.Path(sys.argv[1])
qc_dir      = pathlib.Path(sys.argv[2])
scripts_dir = pathlib.Path(sys.argv[3])
schema_path = pathlib.Path(sys.argv[4])

try:
    with open(sys.argv[5]) as f:
        inp = json.load(f)
except Exception as e:
    print(f"[postedit-check] SKIP: cannot parse hook input: {e}", file=sys.stderr)
    sys.exit(0)

tool = inp.get("tool_name", "")
tool_input = inp.get("tool_input", {}) or {}
session_id = inp.get("session_id", "unknown")

# Extract file path(s)
if tool == "MultiEdit":
    file_path = tool_input.get("file_path", "") or ""
else:
    file_path = tool_input.get("file_path", "") or ""

if not file_path:
    sys.exit(0)

fpath = pathlib.Path(file_path)
fname = fpath.name

def run_qc(cmd, label):
    """Run a QC command; return (rc, stdout+stderr text)."""
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
        return r.returncode, r.stdout + r.stderr
    except FileNotFoundError:
        return -1, f"[{label}] SKIP: script not found"
    except subprocess.TimeoutExpired:
        return -1, f"[{label}] SKIP: timeout"
    except Exception as ex:
        return -1, f"[{label}] SKIP: {ex}"

fails = []

# ── beat_sheet.json ───────────────────────────────────────────────────────────
if fname == "beat_sheet.json":
    reel_dir = fpath.parent

    # (a) JSON schema validation
    if schema_path.exists():
        try:
            import jsonschema
            schema = json.loads(schema_path.read_text())
            sheet  = json.loads(fpath.read_text())
            try:
                jsonschema.validate(instance=sheet, schema=schema)
            except jsonschema.ValidationError as ve:
                fails.append(f"[schema] FAIL: {ve.message[:200]}")
        except ImportError:
            print("[postedit-check] SKIP schema: jsonschema not importable", file=sys.stderr)
        except Exception as e:
            print(f"[postedit-check] SKIP schema: {e}", file=sys.stderr)
    else:
        print("[postedit-check] SKIP schema: schema file absent", file=sys.stderr)

